 "content": "from collections import Counter, defaultdict, deque

def transform(grid):
    """Join matching interior colors of separated framed blocks along rows/columns."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    tiles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            top = min(y for y,x in cells); bottom = max(y for y,x in cells)
            left = min(x for y,x in cells); right = max(x for y,x in cells)
            perimeter = []
            for y,x in cells:
                if y in (top,bottom) or x in (left,right):
                    perimeter.append(grid[y][x])
            frame = Counter(perimeter).most_common(1)[0][0]
            inside = [grid[y][x] for y in range(top+1,bottom) for x in range(left+1,right)]
            signal = None
            if inside and len(set(inside)) == 1 and inside[0] != frame:
                signal = inside[0]
                iy0, iy1 = top+1, bottom
                ix0, ix1 = left+1, right
            else:
                iy0=iy1=ix0=ix1=0
            tiles.append(dict(top=top,bottom=bottom,left=left,right=right,
                              signal=signal,iy0=iy0,iy1=iy1,ix0=ix0,ix1=ix1))

    # On each block row, extend each repeated interior color through the gaps
    # from its first occurrence to its last, without altering any block cells.
    by_row = defaultdict(list)
    by_col = defaultdict(list)
    for t in tiles:
        if t['signal'] is not None:
            by_row[t['top']].append(t)
            by_col[t['left']].append(t)
    for row_tiles in by_row.values():
        colors = defaultdict(list)
        for t in row_tiles:
            colors[t['signal']].append(t)
        for color, group in colors.items():
            if len(group) < 2:
                continue
            leftmost = min(group, key=lambda t:t['left'])
            rightmost = max(group, key=lambda t:t['right'])
            for y in range(max(t['iy0'] for t in group), min(t['iy1'] for t in group)):
                for x in range(leftmost['right']+1, rightmost['left']):
                    if out[y][x] == 0:
                        out[y][x] = color
    for col_tiles in by_col.values():
        colors = defaultdict(list)
        for t in col_tiles:
            colors[t['signal']].append(t)
        for color, group in colors.items():
            if len(group) < 2:
                continue
            topmost = min(group, key=lambda t:t['top'])
            bottommost = max(group, key=lambda t:t['bottom'])
            for x in range(max(t['ix0'] for t in group), min(t['ix1'] for t in group)):
                for y in range(topmost['bottom']+1, bottommost['top']):
                    if out[y][x] == 0:
                        out[y][x] = color
    return out
